<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('credit.view');$customerId=(int)($_GET['customer']??0);$st=db()->prepare('SELECT * FROM customers WHERE id=:id');$st->execute([':id'=>$customerId]);$customer=$st->fetch();if(!$customer){flash('error','Customer not found.');redirect('credit/debts.php');}$led=db()->prepare('SELECT * FROM customer_ledger WHERE customer_id=:id ORDER BY entry_date,id');$led->execute([':id'=>$customerId]);$entries=$led->fetchAll();$pageTitle='Customer Statement';$pageStyles=['admin.css','commerce.css','receipt.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar no-print"><div><a class="back-link" href="<?=e(app_url('customers/view.php?id='.$customerId))?>">← Customer</a><h2>Customer statement</h2><p><?=e($customer['name'])?> · current balance <?=e(money($customer['account_balance']))?></p></div><button class="button button--primary" onclick="window.print()">Print statement</button></div><section class="statement-sheet"><header class="statement-header"><div><strong>Wambo wa Carpets</strong><span>Customer Credit Statement</span></div><div><b><?=e($customer['name'])?></b><span><?=e($customer['phone']?:$customer['email']?:'')?></span><span>Generated <?=e(date('d M Y H:i'))?></span></div></header><table class="statement-table"><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody><?php if(!$entries):?><tr><td colspan="6">No credit transactions.</td></tr><?php else:foreach($entries as$e1):?><tr><td><?=e(format_datetime($e1['entry_date'],'d M Y'))?></td><td><?=e($e1['reference_no']?:'—')?></td><td><?=e($e1['description']?:ucwords(str_replace('_',' ',$e1['entry_type'])))?></td><td><?= (float)$e1['debit_amount']>0?e(money($e1['debit_amount'])):'—'?></td><td><?= (float)$e1['credit_amount']>0?e(money($e1['credit_amount'])):'—'?></td><td><?=e(money($e1['balance_after']))?></td></tr><?php endforeach;endif;?></tbody></table><footer class="statement-balance"><span>Outstanding balance</span><strong><?=e(money($customer['account_balance']))?></strong></footer></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
